import sys
from collections import defaultdict

def find_farthest(node, parent, graph):
    max_distance = 0
    farthest_node = node
    stack = [(node, parent, 0)]
    while stack:
        current, par, dist = stack.pop()
        if dist > max_distance:
            max_distance = dist
            farthest_node = current
        for neighbor in graph[current]:
            if neighbor != par:
                stack.append((neighbor, current, dist + 1))
    return farthest_node, max_distance

def lca(u, v, parent, depth):
    if depth[u] < depth[v]:
        u, v = v, u
    diff = depth[u] - depth[v]
    for i in range(18, -1, -1):
        if diff & (1 << i):
            u = parent[u][i]
    if u != v:
        for i in range(18, -1, -1):
            if parent[u][i] != parent[v][i]:
                u = parent[u][i]
                v = parent[v][i]
        u = parent[u][0]
    return u

def solve(n, edges):
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    farthest, _ = find_farthest(1, -1, graph)
    diameter_end, diameter = find_farthest(farthest, -1, graph)

    parent = [[0] * 18 for _ in range(n + 1)]
    depth = [0] * (n + 1)

    def dfs(node, par, d):
        parent[node][0] = par
        depth[node] = d
        for i in range(1, 18):
            parent[node][i] = parent[parent[node][i - 1]][i - 1]
        for neighbor in graph[node]:
            if neighbor != par:
                dfs(neighbor, node, d + 1)

    dfs(diameter_end, -1, 0)

    max_common = 0
    best_pair = (0, 0, 0, 0)
    max_length = 0

    for u, v in edges:
        l = lca(u, v, parent, depth)
        common_length = depth[u] + depth[v] - 2 * depth[l] + 1
        total_length = diameter - (depth[u] - depth[l]) - (depth[v] - depth[l])
        if common_length > max_common or (common_length == max_common and total_length > max_length):
            max_common = common_length
            max_length = total_length
            best_pair = (diameter_end, u, v, farthest)

    x1, y1, x2, y2 = best_pair
    print(x1, y1)
    print(x2, y2)

input = sys.stdin.read().split()
n = int(input[0])
edges = [(int(input[i * 2 + 1]), int(input[i * 2 + 2])) for i in range(n - 1)]
solve(n, edges)
